const isVersionableItemType = options.itemType['is_versionable'] === '1';
if (!isVersionableItemType) {
	return { hidden: true };
}

const { queryType, queryDate } = options.getState();
const isCurrent = queryType === 'Current';

return {
	disabled: isCurrent,
	value: isCurrent ? null : queryDate
};
